from pathlib import Path
import hashlib,json,re,shutil

SECTIONS={name:'Обзор проекта/'+name for name in ('Эксперименты','План','Запланировано','Проблемы')}


def restore_saved_files(vault,root):
    """Вернуть отсутствующие файлы; существующие и архив никогда не затирать."""
    inventory=json.loads((root/'runs/b123_20261027/graph_fundamental_final/archive_inventory.json').read_text(encoding='utf-8'))
    restored=[]
    for item in inventory['files']:
        target=(vault/item['old_path']).resolve();target.relative_to(vault.resolve())
        if target.exists():continue
        source=(root/item['archive']).resolve();source.relative_to(root.resolve())
        assert hashlib.sha256(source.read_bytes()).hexdigest()==item['sha256'],source
        target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,target)
        assert hashlib.sha256(target.read_bytes()).hexdigest()==item['sha256']
        restored.append(dict(path=item['old_path'],sha256=item['sha256'],source=item['archive']))
    return restored


