def set_visibility(vault,visible):
    visible=sorted(visible)
    assert all((vault/p).is_file() for p in visible)
    # Obsidian использует регулярные выражения JavaScript; эта подгруппа
    # синтаксиса одинакова в Python и JavaScript. Якоря исключают старые копии.
    pattern='^(?:'+'|'.join(re.escape(p).replace('\\ ',' ') for p in visible)+')$'
    query='path:/'+pattern.replace('/','\\/')+'/'
    settings=vault/'.obsidian/graph.json'
    graph=json.loads(settings.read_text(encoding='utf-8'))
    graph.update(search=query,hideUnresolved=True,showAttachments=False,showOrphans=True)
    graph['scale']=0.85
    settings.write_text(json.dumps(graph,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (vault/'.graph-visible.json').write_text(json.dumps(dict(version=1,files=visible,
        regex=pattern,search=query,policy='Only display selected files. Keep every other file intact.'),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')


def visible_files(vault):
    return json.loads((vault/'.graph-visible.json').read_text(encoding='utf-8'))['files']
